// Sources RSS à surveiller (Salesforce ecosystem)
const feeds = [
  {name: 'Salesforce Blog', url: 'https://www.salesforce.com/blog/feed/'},
  {name: 'Salesforce Ben', url: 'https://www.salesforceben.com/feed/'},
  {name: 'Admin Hero', url: 'https://adminhero.com/feed/'}
];

return feeds.map(f => ({json: f}));

const items = $input.all();
const today = new Date();
const yesterday = new Date(today.getTime() - 24*60*60*1000);

// Filtrer les articles des dernières 24h
const recent = items.filter(item => {
  const pubDate = new Date(item.json.pubDate || item.json.isoDate || 0);
  return pubDate >= yesterday;
}).slice(0, 5); // Max 5 articles

if (recent.length === 0) {
  return [{json: {skip: true, message: 'Pas de nouveaux articles'}}];
}

// Préparer le résumé
const articlesText = recent.map(a => `- ${a.json.title}: ${a.json.contentSnippet || a.json.content || ''}`).join('\n');

const prompt = `Tu es un analyste veille concurrentielle pour Digital Humans (automatisation Salesforce par IA).

Analyse ces articles récents de l'écosystème Salesforce:
${articlesText}

Produis:
1. Un résumé des tendances clés (3-5 points)
2. Les opportunités pour Digital Humans
3. Les menaces potentielles
4. Actions recommandées

Réponds en JSON:
{"trends": ["..."], "opportunities": ["..."], "threats": ["..."], "actions": ["..."]}`;

return [{json: {articles_count: recent.length, articles: recent.map(a => ({title: a.json.title, link: a.json.link})), prompt}}];

const filterData = $("Filter Recent").first().json;
// Accepte le format Gemini (candidates) ET le format Ollama (.response),
// pour que le workflow survive a un changement de fournisseur.
const r = $json.response
  || ($json.candidates?.[0]?.content?.parts?.[0]?.text)
  || '';

let analysis = {trends: [], opportunities: [], threats: [], actions: []};

try {
  const jsonMatch = r.match(/\{[\s\S]*trends[\s\S]*\}/);
  if (jsonMatch) {
    analysis = {...analysis, ...JSON.parse(jsonMatch[0])};
  }
} catch(e) {}

return [{json: {
  date: new Date().toISOString().split('T')[0],
  articles_count: filterData.articles_count,
  articles: filterData.articles,
  analysis
}}];

// Transforme les articles de veille en sujets d'article a valider.
// Statut "pending" : rien ne part en redaction sans validation humaine.
// L'agent suggere est deduit du sujet — Sam peut le changer a l'approbation.
const filtre = $("Filter Recent").first().json;
const articles = filtre.articles || [];
const AGENTS = [
  [/lwc|lightning web|composant|component/i, "zara-thompson"],
  [/apex|trigger|classe|code|develop/i,      "diego-martinez"],
  [/flow|automation|admin|permission/i,      "raj-patel"],
  [/agentforce|ia|ai |agent/i,               "marcus-chen"],
  [/data|donnee|migration|integration/i,     "aisha-okonkwo"],
  [/test|qualite|quality/i,                  "elena-volkov"],
  [/deploy|devops|ci\/cd|release/i,          "jordan-blake"],
];
const sortie = [];
for (const a of articles.slice(0, 5)) {
  const titre = (a.title || "").trim();
  if (!titre) continue;
  let agent = "olivia-laurent";
  for (const [re, nom] of AGENTS) { if (re.test(titre)) { agent = nom; break; } }
  sortie.push({ json: {
    title: titre.slice(0, 240),
    description: (a.contentSnippet || a.content || "").replace(/<[^>]+>/g, "").trim().slice(0, 500),
    source_url: a.link || "",
    source_name: a.source || "Veille Salesforce",
    suggested_agent: agent,
    veille_date: new Date().toISOString().slice(0, 10)
  }});
}
return sortie;
